webcomponent.example:
```ts
import { createElement, Save } from "lucide";
renderBox({ tag: "section", class: "flex flex-col gap-4 p-4 bg-card text-card-foreground" }, [
  renderText({ tag: "h2", class: "text-foreground" }, "Title"),
  renderButton({ "aria-label": "Save", class: "bg-primary text-primary-foreground px-4 py-2" }, [
    renderIcon({ size: "sm" }, [createElement(Save)]),
  ]),
]);
```

